// AgentServiceHandler is an implementation of the talgent.agent.private.v1.AgentService service.
type AgentServiceHandler interface {
	// GetWorkStartOptions resolves capabilities for a caller-selected definition or Work.
	GetWorkStartOptions(context.Context, *connect.Request[v1.GetWorkStartOptionsRequest]) (*connect.Response[v11.GetWorkStartOptionsResponse], error)
	// ListWorkStartRepositories discovers the repositories an admitted owner may check out.
	ListWorkStartRepositories(context.Context, *connect.Request[v1.ListWorkStartRepositoriesRequest]) (*connect.Response[v11.WorkStartRepositories], error)
	// GetWorkStartup reads initial rejection, cleanup and outstanding creation facts.
	GetWorkStartup(context.Context, *connect.Request[v1.GetWorkStartupRequest]) (*connect.Response[v1.GetWorkStartupResponse], error)
	// GetWorkOrigin reads retained source attribution for authenticated internal consumers.
	GetWorkOrigin(context.Context, *connect.Request[v1.GetWorkOriginRequest]) (*connect.Response[v1.GetWorkOriginResponse], error)
	// ResolveWorkContextPosition is the Work Context Position Query: it names the
	// position in a Work's context where one of its calls returned, from which a
	// new Work of the same definition may start.
	ResolveWorkContextPosition(context.Context, *connect.Request[v1.ResolveWorkContextPositionRequest]) (*connect.Response[v1.ResolveWorkContextPositionResponse], error)
	// ResolveWorkStarts reports who started each Work of one Project and when, for a Causal Chain.
	ResolveWorkStarts(context.Context, *connect.Request[v1.ResolveWorkStartsRequest]) (*connect.Response[v1.ResolveWorkStartsResponse], error)
	// GetWorkPreparation reads the application-owned initial input and progress.
	GetWorkPreparation(context.Context, *connect.Request[v1.GetWorkPreparationRequest]) (*connect.Response[v1.GetWorkPreparationResponse], error)
	// ListSubmittedPreparations supplies durable admitted facts for business projections.
	ListSubmittedPreparations(context.Context, *connect.Request[v1.ListSubmittedPreparationsRequest]) (*connect.Response[v1.ListSubmittedPreparationsResponse], error)
	// PrepareWorkExecution retains an explicit first-input request and coordinates execution preparation.
	// With creation, request_id is the caller's creation request identity: it
	// yields at most one Work, a repeat returns the original outcome, and a
	// cancelled identity answers FailedPrecondition and creates nothing.
	PrepareWorkExecution(context.Context, *connect.Request[v1.PrepareWorkExecutionRequest]) (*connect.Response[v1.PrepareWorkExecutionResponse], error)
	// GetWorkCreation reads a creation request identity's outcome without advancing it.
	GetWorkCreation(context.Context, *connect.Request[v1.GetWorkCreationRequest]) (*connect.Response[v1.GetWorkCreationResponse], error)
	// CancelWorkCreation settles an unanswered creation request identity: it
	// returns the Work the identity already created, or cancels the identity so
	// that a delayed repeat creates nothing.
	CancelWorkCreation(context.Context, *connect.Request[v1.CancelWorkCreationRequest]) (*connect.Response[v1.CancelWorkCreationResponse], error)
	// VerifyWorkCredential authenticates a native process by the credential of its Work's current live sandbox.
	VerifyWorkCredential(context.Context, *connect.Request[v1.VerifyWorkCredentialRequest]) (*connect.Response[v1.VerifyWorkCredentialResponse], error)
	// GetStartAdmission reads whether a start request was admitted after Work authorization.
	GetStartAdmission(context.Context, *connect.Request[v1.GetStartAdmissionRequest]) (*connect.Response[v1.GetStartAdmissionResponse], error)
	// ChangeAgentDefinitionCapabilities updates future Session capabilities without changing existing snapshots.
	ChangeAgentDefinitionCapabilities(context.Context, *connect.Request[v1.ChangeAgentDefinitionCapabilitiesRequest]) (*connect.Response[v1.ChangeAgentDefinitionCapabilitiesResponse], error)
	// GetAgentDefinition reads the current reusable capability configuration.
	GetAgentDefinition(context.Context, *connect.Request[v1.GetAgentDefinitionRequest]) (*connect.Response[v1.GetAgentDefinitionResponse], error)
	// GetAgentDefinitionForPurpose resolves an internal definition in an authorized usage scope.
	GetAgentDefinitionForPurpose(context.Context, *connect.Request[v1.GetAgentDefinitionForPurposeRequest]) (*connect.Response[v1.GetAgentDefinitionForPurposeResponse], error)
	// ResolveEmployeeAgents reads several employees' own work Agents and their current appearance at once.
	ResolveEmployeeAgents(context.Context, *connect.Request[v1.ResolveEmployeeAgentsRequest]) (*connect.Response[v1.ResolveEmployeeAgentsResponse], error)
	// GetEmployeeAgent reads an employee's own work Agent, or the appearance it would be established with; it never creates one.
	GetEmployeeAgent(context.Context, *connect.Request[v1.GetEmployeeAgentRequest]) (*connect.Response[v1.GetEmployeeAgentResponse], error)
	// ResolveWorkAgents reads the current appearance of several Works' Agents at once.
	ResolveWorkAgents(context.Context, *connect.Request[v1.ResolveWorkAgentsRequest]) (*connect.Response[v1.ResolveWorkAgentsResponse], error)
	// CreateAgentDefinition delegates to the Agent application; acceptance does not imply completion.
	CreateAgentDefinition(context.Context, *connect.Request[v1.CreateAgentDefinitionRequest]) (*connect.Response[v1.CreateAgentDefinitionResponse], error)
	// EnsureAgentDefinition supplies product defaults only for missing state.
	EnsureAgentDefinition(context.Context, *connect.Request[v1.EnsureAgentDefinitionRequest]) (*connect.Response[v1.EnsureAgentDefinitionResponse], error)
	// EnsureEmployeeAgent returns a person's employee definition, which Agent
	// establishes itself from product defaults on its first need.
	EnsureEmployeeAgent(context.Context, *connect.Request[v1.EnsureEmployeeAgentRequest]) (*connect.Response[v1.EnsureEmployeeAgentResponse], error)
	// TransferAgentDefinitionOwners replaces a definition's Owners; every one of
	// its Works answers to them from then on.
	TransferAgentDefinitionOwners(context.Context, *connect.Request[v1.TransferAgentDefinitionOwnersRequest]) (*connect.Response[v1.TransferAgentDefinitionOwnersResponse], error)
	// CreateWork returns the definition's Work for the Subject, creating it when none exists.
	CreateWork(context.Context, *connect.Request[v1.CreateWorkRequest]) (*connect.Response[v1.CreateWorkResponse], error)
	// CancelWorkRegistration fences an unknown initial creation or returns its already admitted Work.
	CancelWorkRegistration(context.Context, *connect.Request[v1.CancelWorkRegistrationRequest]) (*connect.Response[v1.CancelWorkRegistrationResponse], error)
	// LocateWork resolves an existing business binding without creating or starting execution.
	LocateWork(context.Context, *connect.Request[v1.LocateWorkRequest]) (*connect.Response[v1.LocateWorkResponse], error)
	// ResumeWork delegates to the Agent application; acceptance does not imply completion.
	ResumeWork(context.Context, *connect.Request[v1.ResumeWorkRequest]) (*connect.Response[v1.ResumeWorkResponse], error)
	// RestartWork delegates to the Agent application; acceptance does not imply completion.
	RestartWork(context.Context, *connect.Request[v1.RestartWorkRequest]) (*connect.Response[v1.RestartWorkResponse], error)
	// EndWorkExecution ends the Work's Harness process or prevents a pending start request's admission, without closing its conversation.
	EndWorkExecution(context.Context, *connect.Request[v1.EndWorkExecutionRequest]) (*connect.Response[v1.EndWorkExecutionResponse], error)
	// StopWork delegates to the Agent application; acceptance does not imply completion.
	StopWork(context.Context, *connect.Request[v1.StopWorkRequest]) (*connect.Response[v1.StopWorkResponse], error)
	// CloseWork is the one way to close a Work permanently. A stopped or failed
	// Work closes; a running Work is stopped between Turns first and closes once
	// stopped. It is refused while a Turn runs or work is outstanding. Success
	// confirms durable acceptance, not process exit or workspace cleanup.
	CloseWork(context.Context, *connect.Request[v1.CloseWorkRequest]) (*connect.Response[v1.CloseWorkResponse], error)
	// DeliverInput delegates to the Agent application; acceptance does not imply completion.
	DeliverInput(context.Context, *connect.Request[v1.DeliverInputRequest]) (*connect.Response[v1.DeliverInputResponse], error)
	// RespondToInteraction answers a current required user interaction after Session authorization.
	RespondToInteraction(context.Context, *connect.Request[v1.RespondToInteractionRequest]) (*connect.Response[v1.RespondToInteractionResponse], error)
	// GetWork delegates to the Agent application; acceptance does not imply completion.
	GetWork(context.Context, *connect.Request[v1.GetWorkRequest]) (*connect.Response[v1.GetWorkResponse], error)
}

